import { component$, isDev, useVisibleTask$ } from "@qwik.dev/core";
import { RouterOutlet, useQwikRouter } from "@qwik.dev/router";
import { RouterHead } from "./components/router-head/router-head";
import { ConvexProvider } from "./utils/convex-context";
import { AuthProvider } from "./utils/auth-context";
import { PostHogProvider } from "./utils/posthog-context";
import { installLixAuthInterceptor } from "./utils/lix-auth";
import { GlobalConnectivityBanner } from "./components/ui/global-connectivity-banner";
import { GlobalApplicationToasts } from "./components/ui/global-application-toasts";
import { GlobalSpeechPlayer } from "./components/ui/global-speech-player";
import { UsageSyncController } from "./components/desk/usage-sync-controller";
import {
  THEME_BOOTSTRAP_SCRIPT,
  applyTheme,
  readThemePreference,
} from "./utils/theme";

import "./global.css";

const SERVICE_WORKER_REGISTER_SCRIPT = `
if ("serviceWorker" in navigator) {
  navigator.serviceWorker
    .register(${JSON.stringify(`${import.meta.env.BASE_URL}service-worker.js`)})
    .catch((error) => console.error("Twyne service worker registration failed", error));
}
`;

export default component$(() => {
  useQwikRouter({ viewTransition: true });

  const convexUrl = (import.meta.env.PUBLIC_CONVEX_URL ??
    import.meta.env.VITE_CONVEX_URL) as string | undefined;

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(() => {
    installLixAuthInterceptor();

    // The bootstrap script resolves "System" once, at load. Keep following the
    // OS afterwards, so flipping the machine to dark at dusk re-inks the room
    // without a reload. Explicit presets are left alone.
    const query = window.matchMedia("(prefers-color-scheme: dark)");
    const sync = () => {
      const preference = readThemePreference();
      if (preference.preset !== "system") return;
      applyTheme(preference, document.documentElement, query.matches);
    };
    query.addEventListener("change", sync);
    return () => query.removeEventListener("change", sync);
  });

  return (
    <>
      <head>
        <meta charset="utf-8" />
        {/*
          Stamps the writer's palette onto <html> before the first paint.
          It has to be an inline script rather than a component: Qwik
          server-renders the document, so any QRL resumes long after the
          browser has already painted the default cream — which is exactly
          the flash this avoids. The source lives in `utils/theme.ts` so it
          cannot drift from `applyTheme`.
        */}
        <script
          data-theme-bootstrap
          dangerouslySetInnerHTML={THEME_BOOTSTRAP_SCRIPT}
        />
        {!isDev && (
          <link
            rel="manifest"
            href={`${import.meta.env.BASE_URL}manifest.json`}
          />
        )}
        {/* Editorial type stack — Libre Baskerville (display), Lora (body),
            DM Sans (UI), Special Elite (typewriter). Fraunces remains loaded
            for manuscripts that persisted the former display-font mark. */}
        <link rel="preconnect" href="https://fonts.googleapis.com" />
        <link
          rel="preconnect"
          href="https://fonts.gstatic.com"
          crossOrigin="anonymous"
        />
        <link
          rel="stylesheet"
          href="https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,600;9..40,700&family=Fraunces:opsz,wght@9..144,400;9..144,600;9..144,700&family=Libre+Baskerville:ital,wght@0,400;0,700;1,400&family=Lora:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Special+Elite&display=swap"
        />
        <RouterHead />
      </head>
      <body lang="en">
        <GlobalConnectivityBanner />
        <GlobalApplicationToasts />
        <ConvexProvider url={convexUrl}>
          <AuthProvider>
            <PostHogProvider>
              <UsageSyncController />
              <RouterOutlet />
              <GlobalSpeechPlayer />
              {!isDev && (
                <script
                  type="module"
                  dangerouslySetInnerHTML={SERVICE_WORKER_REGISTER_SCRIPT}
                />
              )}
            </PostHogProvider>
          </AuthProvider>
        </ConvexProvider>
      </body>
    </>
  );
});

import { component$, useSignal, useVisibleTask$ } from "@qwik.dev/core";
import { createAppError } from "../../utils/application-errors";
import { ApplicationNotice } from "./application-notice";

/**
 * Application-wide connectivity banner. Inline notices remain the default for
 * a single failed operation; this is reserved for the browser losing its
 * network connection entirely, where every operation would fail. Local editing
 * keeps working and unsynced work stays safe, so the copy reassures rather
 * than blocks.
 */
export const GlobalConnectivityBanner = component$(() => {
  const offline = useSignal(false);

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(
    ({ cleanup }) => {
      if (typeof navigator === "undefined") return;
      const sync = () => {
        offline.value = navigator.onLine === false;
      };
      sync();
      window.addEventListener("online", sync);
      window.addEventListener("offline", sync);
      cleanup(() => {
        window.removeEventListener("online", sync);
        window.removeEventListener("offline", sync);
      });
    },
    { strategy: "document-ready" },
  );

  if (!offline.value) return null;

  return (
    <div class="sticky top-0 z-50 w-full">
      <ApplicationNotice
        variant="outage"
        title="You are offline"
        error={createAppError("NETWORK_UNAVAILABLE", {
          source: "fetch",
          recovery: { action: "check-connection", canRetry: false },
          metadata: { operation: "connectivity" },
        })}
      />
    </div>
  );
});

import { component$, type PropFunction } from "@qwik.dev/core";
import type { LayoutSettings } from "../../types";
import { formatWordCount, readingTimeLabel } from "../../utils/document";
import { formatFolioCount } from "../../utils/draft-thresholds";
import type { EditorStore } from "./editor-state";
import { PageChrome, type PageChromeProps } from "./page-chrome";
import { PageRuler } from "./page-ruler";
import { LastSavedLine } from "./sync-indicator";

export const MANUSCRIPT_READING_ID = "manuscript";

type PageChromeGeometry = Pick<
  PageChromeProps,
  "pageH" | "gap" | "marginTop" | "marginBottom" | "marginLeft" | "marginRight"
>;

interface ManuscriptPanelProps {
  store: EditorStore;
  pageWidthRem: number;
  canvasMinHeight: number;
  pageChromeGeometry: PageChromeGeometry;
  onDragOver$: PropFunction<() => void>;
  onDragLeave$: PropFunction<() => void>;
  onDrop$: PropFunction<() => void>;
  onLayoutChange$: PropFunction<(next: LayoutSettings) => void>;
  onHeaderCommit$: PropFunction<(value: string) => void>;
  onFooterCommit$: PropFunction<(value: string) => void>;
  onJumpToNote$: PropFunction<(position: number) => void>;
}

/**
 * The manuscript surface: ruler, physical page furniture, Tiptap mount,
 * collected notes, and the colophon. It renders editor state but does not own
 * Tiptap, persistence, or cross-panel coordination.
 */
export const ManuscriptPanel = component$<ManuscriptPanelProps>((props) => {
  const { store } = props;
  const onJumpToNote$ = props.onJumpToNote$;

  return (
    <>
      <div
        class="flex-1 overflow-y-auto overflow-x-auto"
        style="background: var(--color-editor-bg);"
        preventdefault:dragover
        preventdefault:dragleave
        preventdefault:drop
        onDragOver$={props.onDragOver$}
        onDragLeave$={props.onDragLeave$}
        onDrop$={props.onDrop$}
      >
        {store.isDragOver && (
          <div class="drag-overlay">
            <span>Drop plate or tabular here</span>
          </div>
        )}

        <PageRuler
          layout={store.layout}
          pageWidthRem={props.pageWidthRem}
          zen={store.zenMode}
          onChange$={props.onLayoutChange$}
        />

        <div
          class={[
            "mx-auto twyne-editor page-canvas relative",
            {
              "show-margin-guides": store.layout.showMarginGuides,
              "zen-mode": store.zenMode,
              "is-paginated": store.paginationActive,
            },
          ]}
          style={{
            ...(store.paginationActive
              ? {
                  width: "var(--page-w)",
                  "flex-shrink": "0",
                  "min-height": `${props.canvasMinHeight}px`,
                }
              : { "max-width": "var(--doc-width, 48rem)" }),
            "padding-left": "var(--doc-pad-left, 3rem)",
            "padding-right": "var(--doc-pad-right, 3rem)",
            "padding-top": "var(--doc-pad-y, 2.5rem)",
            "padding-bottom": "var(--doc-pad-bottom, 4rem)",
          }}
        >
          <PageChrome
            pageCount={store.pageCount}
            active={store.paginationActive}
            layout={store.layout}
            title={store.meta.title}
            headerText={store.headerText}
            footerText={store.footerText}
            zen={store.zenMode}
            onHeaderCommit$={props.onHeaderCommit$}
            onFooterCommit$={props.onFooterCommit$}
            {...props.pageChromeGeometry}
          />

          <div
            id="twyne-editor-mount"
            data-speech-id={MANUSCRIPT_READING_ID}
            data-speech-source="plain"
            style={{ position: "relative", zIndex: 1 }}
          />

          {store.notes.length > 0 && (
            <div
              class="manuscript-notes mt-10 pt-6 border-t border-[var(--color-paper-3)]"
              style="font-family: var(--font-serif);"
            >
              {(["endnote", "footnote"] as const).map((kind) => {
                const items = store.notes.filter((note) => note.kind === kind);
                if (items.length === 0) return null;
                return (
                  <div key={kind} class="manuscript-notes-group">
                    <h3
                      class="dept-label mb-2"
                      style="font-family: var(--font-typewriter); font-size: 0.7rem; letter-spacing: 0.14em; text-transform: uppercase; color: var(--color-ink-muted);"
                    >
                      {kind === "endnote" ? "Notes" : "Footnotes"}
                    </h3>
                    <ol class="manuscript-notes-list">
                      {items.map((note) => (
                        <li key={`${kind}-${note.number}`}>
                          <button
                            type="button"
                            class="manuscript-note-marker"
                            style={{
                              color:
                                kind === "footnote"
                                  ? "var(--color-cobalt)"
                                  : "var(--color-vermilion)",
                            }}
                            onClick$={() => onJumpToNote$(note.pos)}
                            aria-label={`Jump to ${kind} ${note.number} in the text`}
                          >
                            {kind === "footnote"
                              ? `†${note.number}`
                              : note.number}
                          </button>
                          <span class="manuscript-note-text">{note.text}</span>
                        </li>
                      ))}
                    </ol>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      <div
        class="flex items-center justify-between px-5 py-1.5 border-t border-[var(--color-paper-3)] bg-[var(--color-paper-soft)] text-[var(--color-ink-light)] sticky bottom-0"
        style={{
          fontFamily: "var(--font-typewriter)",
          letterSpacing: "0.1em",
          textTransform: "uppercase",
          fontSize: "0.72rem",
          zIndex: "var(--z-sticky)",
        }}
      >
        <span>
          {formatWordCount(store.meta.wordCount)} words ·{" "}
          {formatFolioCount(store.meta.wordCount)} folios
        </span>
        <span>
          <LastSavedLine savedAt={store.lastSavedAt} /> ·{" "}
          {readingTimeLabel(store.meta.readingTime)} · set in Lora &amp;
          Libre Baskerville
        </span>
      </div>
    </>
  );
});
